  "pinyinHtml": "<ruby>一<rt>yī</rt></ruby><ruby>去<rt>qù</rt></ruby><ruby>二<rt>èr</rt></ruby><ruby>三<rt>sān</rt></ruby><ruby>里<rt>lǐ</rt></ruby>，<ruby>烟<rt>yān</rt></ruby><ruby>村<rt>cūn</rt></ruby><ruby>四<rt>sì</rt></ruby><ruby>五<rt>wǔ</rt></ruby><ruby>家<rt>jiā</rt></ruby>。<ruby>亭<rt>tíng</rt></ruby><ruby>台<rt>tái</rt></ruby><ruby>六<rt>liù</rt></ruby><ruby>七<rt>qī</rt></ruby><ruby>座<rt>zuò</rt></ruby>，<ruby>八<rt>bā</rt></ruby><ruby>九<rt>jiǔ</rt></ruby><ruby>十<rt>shí</rt></ruby><ruby>枝<rt>zhī</rt></ruby><ruby>花<rt>huā</rt></ruby>。",
